  1	import java.util.ArrayDeque;
  2	import java.util.ArrayList;
  3	import java.util.Arrays;
  4	import java.util.List;
  5	import java.util.Queue;
  6	
  7	final class BipartiteGraph {
  8	    private BipartiteGraph() {
  9	    }
 10	
 11	    /**
 12	     * @deprecated Use {@link #constructAdjacencyList(int, int[][])}.
 13	     */
 14	    @Deprecated
 15	    static ArrayList<ArrayList<Integer>> constructadj(int vertexCount, int[][] edges) {
 16	        return constructAdjacencyList(vertexCount, edges);
 17	    }
 18	
 19	    static ArrayList<ArrayList<Integer>> constructAdjacencyList(int vertexCount, int[][] edges) {
 20	        return Graph.fromEdges(vertexCount, edges).toAdjacencyList();
 21	    }
 22	
 23	    static boolean isBipartite(int vertexCount, int[][] edges) {
 24	        Graph graph = Graph.fromEdges(vertexCount, edges);
 25	
 26	        Color[] colors = new Color[graph.vertexCount()];
 27	        Arrays.fill(colors, Color.UNCOLORED);
 28	
 29	        for (int vertex = 0; vertex < graph.vertexCount(); vertex++) {
 30	            if (colors[vertex].isUncolored() && !colorComponent(vertex, graph, colors)) {
 31	                return false;
 32	            }
 33	        }
 34	
 35	        return true;
 36	    }
 37	
 38	    private static boolean colorComponent(
 39	            int startVertex,
 40	            Graph graph,
 41	            Color[] colors
 42	    ) {
 43	        Queue<Integer> queue = new ArrayDeque<>();
 44	        colors[startVertex] = Color.FIRST;
 45	        queue.offer(startVertex);
 46	
 47	        while (!queue.isEmpty()) {
 48	            int currentVertex = queue.poll();
 49	            Color currentColor = colors[currentVertex];
 50	
 51	            for (int neighbor : graph.neighborsOf(currentVertex)) {
 52	                if (colors[neighbor].isUncolored()) {
 53	                    colors[neighbor] = currentColor.opposite();
 54	                    queue.offer(neighbor);
 55	                } else if (colors[neighbor] == currentColor) {
 56	                    return false;
 57	                }
 58	            }
 59	        }
 60	
 61	        return true;
 62	    }
 63	
 64	    public static void main(String[] args) {
 65	        int vertexCount = 4;
 66	
 67	        int[][] edges = {{0, 1}, {0, 2}, {1, 2}, {2, 3}};
 68	
 69	        System.out.println(isBipartite(vertexCount, edges));
 70	    }
 71	
 72	    private static final class Graph {
 73	        private static final int EDGE_ENDPOINT_COUNT = 2;
 74	        private static final int SOURCE_VERTEX_INDEX = 0;
 75	        private static final int TARGET_VERTEX_INDEX = 1;
 76	
 77	        private final List<List<Integer>> adjacencyList;
 78	
 79	        private Graph(List<List<Integer>> adjacencyList) {
 80	            this.adjacencyList = adjacencyList;
 81	        }
 82	
 83	        private static Graph fromEdges(int vertexCount, int[][] edges) {
 84	            validateInput(vertexCount, edges);
 85	
 86	            List<List<Integer>> adjacencyList = createEmptyAdjacencyList(vertexCount);
 87	
 88	            for (int[] edge : edges) {
 89	                addUndirectedEdge(
 90	                        adjacencyList,
 91	                        edge[SOURCE_VERTEX_INDEX],
 92	                        edge[TARGET_VERTEX_INDEX]
 93	                );
 94	            }
 95	
 96	            return new Graph(adjacencyList);
 97	        }
 98	
 99	        private int vertexCount() {
100	            return adjacencyList.size();
101	        }
102	
103	        private List<Integer> neighborsOf(int vertex) {
104	            return adjacencyList.get(vertex);
105	        }
106	
107	        private ArrayList<ArrayList<Integer>> toAdjacencyList() {
108	            ArrayList<ArrayList<Integer>> copy = new ArrayList<>(adjacencyList.size());
109	
110	            for (List<Integer> neighbors : adjacencyList) {
111	                copy.add(new ArrayList<>(neighbors));
112	            }
113	
114	            return copy;
115	        }
116	
117	        private static List<List<Integer>> createEmptyAdjacencyList(int vertexCount) {
118	            List<List<Integer>> adjacencyList = new ArrayList<>(vertexCount);
119	
120	            for (int vertex = 0; vertex < vertexCount; vertex++) {
121	                adjacencyList.add(new ArrayList<>());
122	            }
123	
124	            return adjacencyList;
125	        }
126	
127	        private static void addUndirectedEdge(
128	                List<List<Integer>> adjacencyList,
129	                int sourceVertex,
130	                int targetVertex
131	        ) {
132	            adjacencyList.get(sourceVertex).add(targetVertex);
133	            adjacencyList.get(targetVertex).add(sourceVertex);
134	        }
135	
136	        private static void validateInput(int vertexCount, int[][] edges) {
137	            if (vertexCount < 0) {
138	                throw new IllegalArgumentException("vertexCount must be non-negative");
139	            }
140	
141	            if (edges == null) {
142	                throw new IllegalArgumentException("edges must not be null");
143	            }
144	
145	            for (int edgeIndex = 0; edgeIndex < edges.length; edgeIndex++) {
146	                validateEdge(edges[edgeIndex], edgeIndex, vertexCount);
147	            }
148	        }
149	
150	        private static void validateEdge(int[] edge, int edgeIndex, int vertexCount) {
151	            if (edge == null || edge.length != EDGE_ENDPOINT_COUNT) {
152	                throw new IllegalArgumentException(
153	                        "edge at index " + edgeIndex + " must contain exactly two vertices"
154	                );
155	            }
156	
157	            validateVertex(edge[SOURCE_VERTEX_INDEX], edgeIndex, vertexCount);
158	            validateVertex(edge[TARGET_VERTEX_INDEX], edgeIndex, vertexCount);
159	        }
160	
161	        private static void validateVertex(int vertex, int edgeIndex, int vertexCount) {
162	            if (vertex < 0 || vertex >= vertexCount) {
163	                throw new IllegalArgumentException(
164	                        "edge at index " + edgeIndex + " references invalid vertex " + vertex
165	                );
166	            }
167	        }
168	    }
169	
170	    private enum Color {
171	        UNCOLORED,
172	        FIRST,
173	        SECOND;
174	
175	        private boolean isUncolored() {
176	            return this == UNCOLORED;
177	        }
178	
179	        private Color opposite() {
180	            if (this == FIRST) {
181	                return SECOND;
182	            }
183	
184	            if (this == SECOND) {
185	                return FIRST;
186	            }
187	
188	            throw new IllegalStateException("Uncolored vertices do not have an opposite color");
189	        }
190	    }
191	}
